const src = $json.body ?? $json;
const required = ['clinic_id','dentist_id','service_id','date'];
for (const key of required) {
  if (!String(src[key] ?? '').trim()) throw new Error(key + ' is required');
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(src.date))) {
  throw new Error('date must use YYYY-MM-DD');
}
const part = String(src.part_of_day ?? 'any').toLowerCase();
if (!['any','morning','afternoon','evening'].includes(part)) {
  throw new Error('part_of_day must be any, morning, afternoon, or evening');
}
return [{json:{
  clinic_id:String(src.clinic_id),
  dentist_id:String(src.dentist_id),
  service_id:String(src.service_id),
  date:String(src.date),
  part_of_day:part
}}];

const req = $('Normalize Availability Request').first().json;
const context = $json;
if (!context?.clinic || !context?.dentist || !context?.service) {
  throw new Error('Clinic, dentist, or service configuration not found');
}
const schedule = Array.isArray(context.schedule) ? context.schedule : [];
if (!schedule.length) {
  return [{json:{...req, context, no_working_hours:true, calendar_id:context.dentist.google_calendar_id || '', day_start:req.date+'T00:00:00', day_end:req.date+'T23:59:59'}}];
}
return [{json:{
  ...req,
  context,
  no_working_hours:false,
  calendar_id:String(context.dentist.google_calendar_id ?? ''),
  day_start:req.date+'T00:00:00',
  day_end:req.date+'T23:59:59'
}}];

const req = $('Prepare Calendar Query').first().json;
const context = req.context;
const tz = context.clinic.timezone || 'Asia/Kolkata';
const busyRaw = $json?.calendars?.[req.calendar_id]?.busy ?? [];
const schedules = Array.isArray(context.schedule) ? context.schedule : [];
const closures = Array.isArray(context.closures) ? context.closures : [];
const appts = Array.isArray(context.appointments) ? context.appointments : [];
const duration = Number(context.service.duration_minutes || 30);
const buffer = Number(context.service.buffer_minutes || 0);
const interval = Number(context.clinic.slot_interval_minutes || 30);

function zonedDateTimeToUtc(dateStr,timeStr,timeZone){
  const [y,m,d]=dateStr.split('-').map(Number);
  const [hh,mm,ss=0]=timeStr.split(':').map(Number);
  let guess=new Date(Date.UTC(y,m-1,d,hh,mm,ss));
  const fmt=new Intl.DateTimeFormat('en-US',{
    timeZone,year:'numeric',month:'2-digit',day:'2-digit',
    hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'
  });
  for(let n=0;n<2;n++){
    const p=Object.fromEntries(fmt.formatToParts(guess).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));
    const represented=Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day),Number(p.hour),Number(p.minute),Number(p.second));
    const wanted=Date.UTC(y,m-1,d,hh,mm,ss);
    guess=new Date(guess.getTime() + (wanted-represented));
  }
  return guess;
}
function overlaps(start,end,rangeStart,rangeEnd){
  return start < rangeEnd && end > rangeStart;
}
function matchesPart(date){
  const h=Number(new Intl.DateTimeFormat('en-US',{timeZone:tz,hour:'2-digit',hourCycle:'h23'}).format(date));
  if(req.part_of_day==='morning') return h<12;
  if(req.part_of_day==='afternoon') return h>=12 && h<17;
  if(req.part_of_day==='evening') return h>=17;
  return true;
}

const busy=[
  ...busyRaw.map(x=>({start:new Date(x.start),end:new Date(x.end),source:'google'})),
  ...appts.map(x=>({start:new Date(x.start_time),end:new Date(x.end_time),source:'appointment'})),
  ...closures.map(x=>({start:new Date(x.starts_at),end:new Date(x.ends_at),source:'closure'}))
];

const slots=[];
for(const row of schedules){
  let cursor=zonedDateTimeToUtc(req.date,String(row.start_time).slice(0,8),tz);
  const windowEnd=zonedDateTimeToUtc(req.date,String(row.end_time).slice(0,8),tz);
  while(cursor < windowEnd){
    const serviceEnd=new Date(cursor.getTime()+duration*60000);
    const blockedEnd=new Date(serviceEnd.getTime()+buffer*60000);
    if(blockedEnd<=windowEnd && matchesPart(cursor)){
      const blocked=busy.some(b=>overlaps(cursor,blockedEnd,b.start,b.end));
      if(!blocked){
        slots.push({
          start:cursor.toISOString(),
          end:serviceEnd.toISOString(),
          dentist_id:req.dentist_id,
          service_id:req.service_id
        });
      }
    }
    cursor=new Date(cursor.getTime()+interval*60000);
  }
}
return [{json:{
  available:slots.length>0,
  clinic_id:req.clinic_id,
  dentist_id:req.dentist_id,
  dentist_name:context.dentist.dentist_name,
  service_id:req.service_id,
  service_name:context.service.service_name,
  date:req.date,
  timezone:tz,
  slots:slots.slice(0,5)
}}];
